const state = {view:'inbox', bulkCreateOpen:false, contacts:[], messages:[], conversations:[], campaigns:[], forwardingRules:[], leadImports:[], templates:[], activeLeadImport:null, selectedLeadRecords:new Set(), leadFilter:'all', search:'', selectedContacts:new Set(), activeConversation:null, composeContextEmail:null};
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const content = $('#content');

function icons(){ if(window.lucide) lucide.createIcons({attrs:{'stroke-width':1.8}}); }
function escapeHtml(value=''){ const d=document.createElement('div'); d.textContent=String(value); return d.innerHTML; }
function formatDate(value){ if(!value) return '—'; const d=new Date(value); return d.toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}); }
function initials(value=''){ return value.trim().slice(0,2).toUpperCase() || 'M'; }
function safeHttpUrl(value=''){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:'';}catch{return '';}}
function toast(message,type=''){ const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=message; $('#toastStack').append(el); setTimeout(()=>el.remove(),3500); }
async function api(url, options={}){
  const response=await fetch(url,options); let body={};
  try{body=await response.json()}catch{}
  if(response.status===401){location.reload(); throw new Error('登录已过期');}
  if(!response.ok) throw new Error(body.error||`请求失败 (${response.status})`);
  return body;
}
function setTitle(title,eyebrow='ZHANYI MAIL'){ $('#pageTitle').textContent=title; $('#pageEyebrow').textContent=eyebrow; }
function setActiveNav(){ $$('.nav-item,.compose-nav').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view)); }
function emptyState(icon,title,text='') { return `<div class="empty"><i data-lucide="${icon}"></i><h3>${escapeHtml(title)}</h3><p>${escapeHtml(text)}</p></div>`; }
function statusLabel(status){const labels={received:'已接收',sent:'已发送',delivered:'已送达',queued:'等待中',processing:'处理中',sending:'发送中',completed:'已完成',cancelled:'已取消',failed:'失败',bounced:'退信',complained:'投诉',delayed:'延迟'};return labels[status]||status;}
function openModal(html,wide=false){$('#modal').innerHTML=html;$('#modal').className=`modal${wide?' wide':''}`;$('#modalBackdrop').classList.remove('hidden');icons();}
function closeModal(){ $('#modalBackdrop').classList.add('hidden'); $('#modal').innerHTML=''; }

async function loadSummary(){
  const s=await api('/api/summary');
  $('#inboxCount').textContent=s.inbox||''; $('#sentCount').textContent=s.sent||'';
  $('#contactCount').textContent=s.contacts||''; $('#campaignCount').textContent=s.active_campaigns||'';
  $('#forwardingCount').textContent=s.forwarding_rules||'';
  $('#leadImportCount').textContent=s.lead_imports||'';
}

async function renderMail(direction){
  if(direction==='inbound'){await renderInbox();return;}
  state.view=direction==='inbound'?'inbox':'sent'; setActiveNav(); setTitle(direction==='inbound'?'收件箱':'已发送',direction==='inbound'?'INBOX':'SENT');
  content.innerHTML=$('#mailListTemplate').innerHTML; icons();
  const q=encodeURIComponent(state.search); state.messages=await api(`/api/messages?direction=${direction}&q=${q}`);
  $('#listMeta').textContent=`${state.messages.length} 封邮件`;
  const list=$('#mailList');
  if(!state.messages.length){list.innerHTML=emptyState(direction==='inbound'?'inbox':'send',direction==='inbound'?'暂无收件':'暂无发送记录');icons();return;}
  list.innerHTML=state.messages.map(m=>{
    const primary=direction==='inbound'?m.from_email:(m.to||[]).join(', ');
    const secondary=direction==='inbound'?(m.to||[]).join(', '):(m.from_email||ZHANYI_FROM);
    const preview=(m.text_body||'').replace(/\s+/g,' ').slice(0,110);
    return `<article class="mail-row" data-id="${m.id}"><div class="mail-sender"><div class="avatar">${escapeHtml(initials(primary))}</div><div class="mail-sender-text"><strong>${escapeHtml(primary||'未知发件人')}</strong><span>${escapeHtml(secondary)}</span></div></div><div class="mail-subject"><strong>${escapeHtml(m.subject||'(无主题)')}</strong><span>${escapeHtml(preview)}</span></div><div class="mail-time"><span class="status ${escapeHtml(m.status)}">${escapeHtml(statusLabel(m.status))}</span><br>${formatDate(m.received_at||m.sent_at||m.created_at)}</div></article>`;
  }).join('');
  $$('.mail-row',list).forEach(row=>row.onclick=()=>renderMessage(Number(row.dataset.id)));
}

async function renderInbox(){
  state.view='inbox';state.activeConversation=null;setActiveNav();setTitle('收件箱','CONVERSATIONS');
  content.innerHTML=$('#mailListTemplate').innerHTML;icons();
  state.conversations=await api(`/api/conversations?q=${encodeURIComponent(state.search)}`);
  const inboundTotal=state.conversations.reduce((sum,item)=>sum+item.inbound_count,0);
  $('#listMeta').textContent=`${state.conversations.length} 位客户 · ${inboundTotal} 封来信`;
  const list=$('#mailList');
  if(!state.conversations.length){list.innerHTML=emptyState('messages-square','暂无客户会话');icons();return;}
  list.innerHTML=state.conversations.map(c=>`<article class="mail-row conversation-row" data-email="${encodeURIComponent(c.email)}"><div class="mail-sender"><div class="avatar">${escapeHtml(initials(c.display_name))}</div><div class="mail-sender-text"><strong>${escapeHtml(c.display_name)}</strong><span>${escapeHtml(c.company||c.email)}</span></div></div><div class="mail-subject"><strong>${escapeHtml(c.latest_subject||'(无主题)')}</strong><span>${escapeHtml(c.latest_preview||'')}</span></div><div class="mail-time"><span class="conversation-count">${c.message_count} 封往来</span><br>${formatDate(c.latest_at)}</div></article>`).join('');
  $$('.conversation-row',list).forEach(row=>row.onclick=()=>renderConversation(decodeURIComponent(row.dataset.email)));
}

async function renderConversation(email){
  const thread=await api(`/api/conversation?email=${encodeURIComponent(email)}`);state.view='inbox';state.activeConversation=email;setActiveNav();
  const name=thread.contact?`${thread.contact.first_name||''} ${thread.contact.last_name||''}`.trim():'';
  setTitle(name||email,'CUSTOMER THREAD');
  const latestInbound=[...thread.messages].reverse().find(m=>m.direction==='inbound');
  const replySubject=latestInbound?`回复：${latestInbound.subject||''}`:'';
  content.innerHTML=`<div class="section-head"><button class="secondary" id="backToInbox"><i data-lucide="arrow-left"></i>收件箱</button><button class="primary" id="replyConversation"><i data-lucide="reply"></i>回复</button></div><section class="thread-panel"><header class="thread-header"><div class="avatar large">${escapeHtml(initials(name||email))}</div><div><h2>${escapeHtml(name||email)}</h2><span>${escapeHtml(email)}${thread.contact?.company?' · '+escapeHtml(thread.contact.company):''}</span></div><strong>${thread.messages.length} 封往来</strong></header><div class="thread-list">${thread.messages.map(m=>`<article class="thread-item ${m.direction}" data-id="${m.id}"><div class="thread-meta"><span class="thread-meta-left"><span class="direction-label ${m.direction}"><i data-lucide="${m.direction==='inbound'?'arrow-down-left':'arrow-up-right'}"></i>${m.direction==='inbound'?'客户来信':'我们发送'}</span>${m.bulk?'<span class="tag ai-tag">批量发送</span>':''}</span><time>${formatDate(m.received_at||m.sent_at||m.created_at)}</time></div><strong>${escapeHtml(m.subject||'(无主题)')}</strong><p>${escapeHtml(m.preview||'')}</p><span class="status ${escapeHtml(m.status)}">${escapeHtml(statusLabel(m.status))}</span></article>`).join('')}</div></section>`;
  $('#backToInbox').onclick=renderInbox;
  $('#replyConversation').onclick=()=>renderCompose({emails:[email],subject:replySubject,contextEmail:email});
  $$('.thread-item').forEach(item=>item.onclick=()=>{const msg=thread.messages.find(x=>String(x.id)===item.dataset.id);if(msg&&msg.bulk){campaignDetail(msg.campaign_id);}else{renderMessage(Number(item.dataset.id),{backConversation:email});}});icons();
}

async function renderMessage(id,options={}){
  const m=await api(`/api/messages/${id}`); setTitle(m.subject||'(无主题)','MESSAGE');
  const body=m.html_body||`<pre style="white-space:pre-wrap;font:inherit">${escapeHtml(m.text_body||'')}</pre>`;
  const attachments=(m.attachments||[]).map(a=>`<a class="secondary" href="/api/attachments/${a.id}"><i data-lucide="paperclip"></i>${escapeHtml(a.filename)}</a>`).join('');
  content.innerHTML=`<div class="section-head"><div class="button-row"><button class="secondary" id="backToList"><i data-lucide="arrow-left"></i>返回</button>${m.direction==='inbound'?'<button class="primary" id="replyMessage"><i data-lucide="reply"></i>回复</button>':''}</div><span class="status ${escapeHtml(m.status)}">${escapeHtml(statusLabel(m.status))}</span></div><article class="message-detail"><header class="message-detail-head"><h2>${escapeHtml(m.subject||'(无主题)')}</h2><div class="address-line"><span>发件人</span><strong>${escapeHtml(m.from_email)}</strong></div><div class="address-line"><span>收件人</span><div>${escapeHtml((m.to||[]).join(', '))}</div></div><div class="address-line"><span>时间</span><div>${formatDate(m.received_at||m.sent_at||m.created_at)}</div></div></header><div class="message-body"><iframe class="message-frame" id="messageFrame" sandbox="allow-popups" title="邮件正文"></iframe></div>${attachments?`<div class="attachment-strip">${attachments}</div>`:''}</article>`;
  $('#messageFrame').srcdoc=`<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><style>body{font:14px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#17202a;padding:20px;margin:0;overflow-wrap:anywhere}img{max-width:100%;height:auto}table{max-width:100%}a{color:#2463a8}</style></head><body>${body}</body></html>`;
  $('#backToList').onclick=()=>options.backConversation?renderConversation(options.backConversation):renderMail(m.direction); icons();
  if($('#replyMessage')) $('#replyMessage').onclick=()=>renderCompose({emails:[m.from_email],subject:`回复：${m.subject||''}`,contextEmail:m.from_email});
}

async function renderContacts(){
  state.view='contacts';setActiveNav();setTitle('联系人','CUSTOMERS');
  state.contacts=await api(`/api/contacts?q=${encodeURIComponent(state.search)}`);
  content.innerHTML=`<div class="section-head"><div><h2>客户通讯录</h2><span class="muted">${state.contacts.length} 位联系人</span></div><div class="button-row"><input class="hidden" type="file" id="csvInput" accept=".csv,text/csv"><button class="secondary" id="importButton"><i data-lucide="file-up"></i>导入 CSV</button><button class="primary" id="addContact"><i data-lucide="user-plus"></i>新建联系人</button></div></div><div class="data-panel">${state.contacts.length?`<table class="data-table"><thead><tr><th>姓名</th><th>邮箱</th><th>公司</th><th>标签</th><th>状态</th><th></th></tr></thead><tbody>${state.contacts.map(c=>`<tr><td class="contact-name"><strong>${escapeHtml(`${c.first_name} ${c.last_name}`.trim()||'—')}</strong><span>${escapeHtml(c.notes||'')}</span></td><td>${escapeHtml(c.email)}</td><td>${escapeHtml(c.company||'—')}</td><td>${(c.tags||'').split(',').filter(Boolean).map(t=>`<span class="tag">${escapeHtml(t.trim())}</span>`).join('')||'—'}</td><td><span class="status ${c.status==='active'?'delivered':'failed'}">${c.status==='active'?'可联系':'已退订'}</span></td><td class="actions"><button class="text-button edit-contact" data-id="${c.id}">编辑</button></td></tr>`).join('')}</tbody></table>`:emptyState('contact-round','暂无联系人') }</div>`;
  $('#addContact').onclick=()=>contactModal(); $$('.edit-contact').forEach(b=>b.onclick=()=>contactModal(state.contacts.find(c=>c.id===Number(b.dataset.id))));
  $('#importButton').onclick=()=>$('#csvInput').click(); $('#csvInput').onchange=importCsv; icons();
}

function contactModal(contact={}){
  openModal(`<form id="contactForm"><div class="modal-header"><h2>${contact.id?'编辑联系人':'新建联系人'}</h2><button type="button" class="icon-button modal-close"><i data-lucide="x"></i></button></div><div class="modal-body"><div class="form-grid"><label class="field"><span>名</span><input name="first_name" value="${escapeHtml(contact.first_name||'')}"></label><label class="field"><span>姓</span><input name="last_name" value="${escapeHtml(contact.last_name||'')}"></label><label class="field span-2"><span>邮箱</span><input type="email" name="email" required value="${escapeHtml(contact.email||'')}"></label><label class="field"><span>公司</span><input name="company" value="${escapeHtml(contact.company||'')}"></label><label class="field"><span>状态</span><select name="status"><option value="active" ${contact.status!=='unsubscribed'?'selected':''}>可联系</option><option value="unsubscribed" ${contact.status==='unsubscribed'?'selected':''}>已退订</option></select></label><label class="field span-2"><span>标签</span><input name="tags" value="${escapeHtml(contact.tags||'')}"></label><label class="field span-2"><span>备注</span><textarea name="notes">${escapeHtml(contact.notes||'')}</textarea></label></div><p class="form-error" id="contactError"></p></div><div class="modal-footer">${contact.id?'<button type="button" class="danger" id="deleteContact"><i data-lucide="trash-2"></i>删除</button>':''}<button type="button" class="secondary modal-close">取消</button><button class="primary" type="submit">保存</button></div></form>`);
  $$('.modal-close').forEach(b=>b.onclick=closeModal); const form=$('#contactForm');
  form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{await api(contact.id?`/api/contacts/${contact.id}`:'/api/contacts',{method:contact.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();toast('联系人已保存');await renderContacts();await loadSummary();}catch(err){$('#contactError').textContent=err.message;}};
  if(contact.id)$('#deleteContact').onclick=async()=>{if(!confirm('确定删除该联系人？'))return;await api(`/api/contacts/${contact.id}`,{method:'DELETE'});closeModal();toast('联系人已删除');await renderContacts();await loadSummary();};
}

async function importCsv(event){const file=event.target.files[0];if(!file)return;const data=new FormData();data.append('file',file);try{const r=await api('/api/contacts/import',{method:'POST',body:data});toast(`导入完成：新增 ${r.created}，更新 ${r.updated}，跳过 ${r.skipped}`);await renderContacts();await loadSummary();}catch(err){toast(err.message,'error');}}

function leadBreakdown(items,total,kind){
  if(!items?.length)return emptyState('chart-no-axes-column','暂无统计数据');
  const max=Math.max(...items.map(item=>item.count),1);
  return `<div class="lead-breakdown ${kind}">${items.map(item=>`<div class="lead-breakdown-row"><div><span title="${escapeHtml(item.label)}">${escapeHtml(item.label)}</span><strong>${item.count}</strong></div><div class="lead-bar"><i style="width:${Math.max(4,item.count/max*100)}%"></i></div><small>${total?Math.round(item.count/total*100):0}%</small></div>`).join('')}</div>`;
}

function visibleLeadRecords(){
  const detail=state.activeLeadImport;if(!detail)return[];const q=state.search.trim().toLowerCase();
  return detail.records.filter(row=>(state.leadFilter!=='email'||row.emails?.length)&&(!q||`${row.company} ${row.contact_name} ${row.title} ${row.country} ${row.product} ${row.match_reason} ${(row.emails||[]).join(' ')} ${row.phone} ${row.website}`.toLowerCase().includes(q)));
}

function updateLeadSelectionControls(records=visibleLeadRecords()){
  const detailIds=new Set((state.activeLeadImport?.records||[]).map(row=>row.id));state.selectedLeadRecords=new Set([...state.selectedLeadRecords].filter(id=>detailIds.has(id)));
  const count=state.selectedLeadRecords.size;const label=$('#leadSelectedCount');const button=$('#addSelectedContacts');const all=$('#leadSelectAll');if(label)label.textContent=`已选择 ${count} 条`;if(button){button.disabled=!count;button.innerHTML=`<i data-lucide="user-round-plus"></i>添加为联系人${count?` (${count})`:''}`;}if(all){all.checked=!!records.length&&records.every(row=>state.selectedLeadRecords.has(row.id));all.indeterminate=records.some(row=>state.selectedLeadRecords.has(row.id))&&!all.checked;}icons();
}

function renderLeadImportTable(){
  const detail=state.activeLeadImport;const body=$('#leadRecordBody');const meta=$('#leadRecordMeta');if(!detail||!body)return;const records=visibleLeadRecords();
  $$('.lead-filter button').forEach(button=>button.classList.toggle('active',button.dataset.leadFilter===state.leadFilter));meta.textContent=state.search||state.leadFilter==='email'?`显示 ${records.length} / ${detail.total_rows} 条`:`${detail.total_rows} 条线索`;
  if(!records.length){body.innerHTML=`<tr><td colspan="7">${emptyState('search','没有匹配的线索')}</td></tr>`;updateLeadSelectionControls(records);return;}
  body.innerHTML=records.map(row=>{
    const website=safeHttpUrl(row.website);const emails=(row.emails||[]).map(email=>`<a href="mailto:${escapeHtml(email)}">${escapeHtml(email)}</a>`).join('');
    const action=row.emails?.length?`<button class="secondary lead-compose" data-id="${row.id}"><i data-lucide="square-pen"></i>写邮件</button>${row.is_duplicate?'<span class="lead-duplicate-note">重复线索</span>':''}`:'<span class="lead-flag incomplete">待补邮箱</span>';
    return `<tr><td class="lead-select"><input class="checkbox lead-check" type="checkbox" value="${row.id}" ${state.selectedLeadRecords.has(row.id)?'checked':''} aria-label="选择第 ${row.source_row} 行"></td><td class="lead-index">${row.source_row}</td><td class="contact-name"><strong>${escapeHtml(row.company||'未填写公司')}</strong><span>${escapeHtml(row.contact_name||'未填写联系人')}${row.title?' · '+escapeHtml(row.title):''}</span></td><td><strong>${escapeHtml(row.country||'未填写')}</strong><span class="lead-subline">${escapeHtml(row.product||'未填写产品')}</span></td><td class="lead-contact-cell">${emails||'<span class="muted">无邮箱</span>'}${row.phone?`<span>${escapeHtml(row.phone)}</span>`:''}${website?`<a href="${escapeHtml(website)}" target="_blank" rel="noopener">打开官网</a>`:''}</td><td class="lead-reason">${escapeHtml(row.match_reason||'—')}</td><td class="lead-action-cell">${action}</td></tr>`;
  }).join('');
  $$('.lead-check',body).forEach(input=>input.onchange=()=>{input.checked?state.selectedLeadRecords.add(Number(input.value)):state.selectedLeadRecords.delete(Number(input.value));updateLeadSelectionControls(records);});$$('.lead-compose',body).forEach(button=>button.onclick=()=>{const row=detail.records.find(item=>item.id===Number(button.dataset.id));if(row?.emails?.length)renderCompose({emails:row.emails});});const all=$('#leadSelectAll');if(all)all.onchange=()=>{records.forEach(row=>all.checked?state.selectedLeadRecords.add(row.id):state.selectedLeadRecords.delete(row.id));renderLeadImportTable();};updateLeadSelectionControls(records);
}

async function addSelectedLeadsToContacts(){
  const ids=[...state.selectedLeadRecords];if(!ids.length){toast('请先选择需要添加的线索','error');return;}const button=$('#addSelectedContacts');button.disabled=true;
  try{const result=await api(`/api/lead-imports/${state.activeLeadImport.id}/contacts`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({record_ids:ids})});state.selectedLeadRecords=new Set();await loadSummary();renderLeadImportTable();toast(`联系人处理完成：新增 ${result.created}，已存在 ${result.existing}，跳过 ${result.skipped}`);}catch(err){toast(err.message,'error');button.disabled=false;}
}

async function loadLeadImportDetail(importId){
  state.activeLeadImport=await api(`/api/lead-imports/${importId}`);state.selectedLeadRecords=new Set();state.leadFilter='all';const detail=state.activeLeadImport;const dashboard=$('#leadImportDashboard');
  dashboard.innerHTML=`<div class="lead-import-toolbar"><div><strong>${escapeHtml(detail.filename)}</strong><span>${escapeHtml(detail.sheet_name)} · ${formatDate(detail.created_at)}</span></div><label>历史记录<select id="leadImportSelect">${state.leadImports.map(item=>`<option value="${item.id}" ${item.id===detail.id?'selected':''}>${escapeHtml(item.filename)} · ${item.total_rows} 条</option>`).join('')}</select></label></div><div class="lead-metrics"><div class="metric"><span>全部线索</span><strong>${detail.total_rows}</strong></div><div class="metric"><span>公司数量</span><strong>${detail.company_count}</strong></div><div class="metric"><span>含邮箱</span><strong>${detail.email_rows}</strong><small>${detail.total_rows?Math.round(detail.email_rows/detail.total_rows*100):0}% 覆盖</small></div><div class="metric"><span>含电话</span><strong>${detail.phone_rows}</strong><small>${detail.total_rows?Math.round(detail.phone_rows/detail.total_rows*100):0}% 覆盖</small></div><div class="metric"><span>含官网</span><strong>${detail.website_rows}</strong><small>${detail.total_rows?Math.round(detail.website_rows/detail.total_rows*100):0}% 覆盖</small></div><div class="metric"><span>重复线索</span><strong>${detail.duplicate_rows}</strong><small>跨历史批次识别</small></div></div><div class="lead-analysis"><section><header><h3>国家/地区分布</h3><span>${detail.countries.length} 个地区</span></header>${leadBreakdown(detail.countries,detail.total_rows,'countries')}</section><section><header><h3>产品分布</h3><span>前 ${detail.products.length} 类</span></header>${leadBreakdown(detail.products,detail.total_rows,'products')}</section></div><div class="section-head lead-table-head"><h2>解析结果</h2><span class="muted" id="leadRecordMeta"></span></div><div class="lead-table-controls"><div class="segmented lead-filter"><button class="active" data-lead-filter="all">全部线索</button><button data-lead-filter="email">仅含邮箱</button></div><div class="lead-bulk-actions"><button class="secondary" id="selectVisibleLeads"><i data-lucide="list-checks"></i>全选当前</button><button class="icon-button" id="clearLeadSelection" title="清空选择"><i data-lucide="x"></i></button><span id="leadSelectedCount">已选择 0 条</span><button class="primary" id="addSelectedContacts" disabled><i data-lucide="user-round-plus"></i>添加为联系人</button></div></div><div class="data-panel lead-table-wrap"><table class="data-table lead-table"><thead><tr><th><input class="checkbox" id="leadSelectAll" type="checkbox" aria-label="全选当前结果"></th><th>行</th><th>公司 / 联系人</th><th>地区 / 产品</th><th>联系方式</th><th>匹配理由</th><th>操作</th></tr></thead><tbody id="leadRecordBody"></tbody></table></div>`;
  $('#leadImportSelect').onchange=event=>loadLeadImportDetail(Number(event.target.value)).catch(err=>toast(err.message,'error'));$$('.lead-filter button').forEach(button=>button.onclick=()=>{state.leadFilter=button.dataset.leadFilter;renderLeadImportTable();});$('#selectVisibleLeads').onclick=()=>{visibleLeadRecords().forEach(row=>state.selectedLeadRecords.add(row.id));renderLeadImportTable();};$('#clearLeadSelection').onclick=()=>{state.selectedLeadRecords=new Set();renderLeadImportTable();};$('#addSelectedContacts').onclick=addSelectedLeadsToContacts;renderLeadImportTable();icons();
}

async function uploadLeadFile(file){
  if(!file)return;const suffix=file.name.toLowerCase().split('.').pop();if(!['xlsx','csv'].includes(suffix)){toast('仅支持 .xlsx 或 .csv 文件','error');return;}if(file.size>10*1024*1024){toast('线索文件不能超过 10 MB','error');return;}
  const zone=$('#leadDropZone');const status=$('#leadUploadStatus');zone.classList.add('uploading');status.textContent=`正在解析 ${file.name}…`;const data=new FormData();data.append('file',file);
  try{const result=await api('/api/lead-imports',{method:'POST',body:data});toast(`解析完成：${result.total_rows} 条线索，${result.email_rows} 条含邮箱`);await loadSummary();await renderLeadImports(result.id);}catch(err){toast(err.message,'error');status.textContent='解析失败，请检查文件模板后重试';zone.classList.remove('uploading');}
}

