  state.view='lead-imports';setActiveNav();setTitle('批量解析','LEAD PARSER');content.innerHTML=`<section class="lead-upload"><label class="lead-drop-zone" id="leadDropZone" tabindex="0"><input class="hidden" type="file" id="leadFileInput" accept=".xlsx,.csv"><i data-lucide="file-up"></i><div><strong>拖入客户线索表格</strong><span id="leadUploadStatus">支持 Excel .xlsx 和 CSV，字段按照固定线索模板自动识别</span></div><button class="secondary" type="button" id="leadChooseFile"><i data-lucide="folder-open"></i>选择文件</button></label></section><div id="leadImportDashboard"></div>`;
