function directRecipientEntries(){return ($('#directRecipients')?.value||'').split(/[\n,;]+/).map(v=>v.trim()).filter(Boolean);}
function directRecipientEmails(){return [...new Set(directRecipientEntries().map(v=>v.toLowerCase()))];}
function composeRecipientEmails(){const selected=[...state.selectedContacts].map(id=>state.contacts.find(c=>c.id===id)?.email).filter(Boolean);return [...new Set([...selected,...directRecipientEmails()].map(v=>v.toLowerCase()))];}
function getComposeRecipientEmail(){
  const recipients=composeRecipientEmails();
  return recipients.length===1?recipients[0]:'';
}
function selectedContactEmails(){return [...state.selectedContacts].map(id=>state.contacts.find(c=>c.id===id)?.email).filter(Boolean);}
function syncRecipientField(){const input=$('#directRecipients');if(!input)return;const selected=selectedContactEmails();const manual=directRecipientEntries().filter(value=>!selected.includes(value.toLowerCase()));input.value=[...selected,...manual].join(', ');}
function updateAiContext(reveal=false){const emails=composeRecipientEmails();const single=emails.length===1?emails[0]:null;state.composeContextEmail=single;if(reveal&&single)$('#aiAssistant')?.classList.remove('hidden');const status=$('#aiStatus');if(status)status.textContent=single?`已关联 ${single} 的客户资料与往来记录`:'选择一位收件人后可读取往来记录与联系人资料';}
function updateRecipientSelection(){syncRecipientField();updateSelectedCount();updateAiContext(true);}

async function runAiDraft(mode){
  const email=getComposeRecipientEmail();if(!email){toast('请只选择一位客户，再使用 AI 写作','error');return;}
  const buttons=$$('.ai-action');const status=$('#aiStatus');buttons.forEach(button=>button.disabled=true);status.textContent='AI 正在整理往来记录并生成文案…';
  try{
    const result=await api('/api/ai/draft',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email,mode,instruction:$('#aiInstruction').value.trim(),subject:$('#subject').value.trim(),current_html:$('#editor').innerHTML,from_email:$('#senderEmail').value.trim()})});
    if(result.subject)$('#subject').value=result.subject;$('#editor').innerHTML=result.html;state.composeContextEmail=email;status.textContent=`已参考 ${result.context_count} 封往来 · ${result.model}`;toast(mode==='draft'?'AI 草稿已生成':'邮件文案已更新');
  }catch(err){status.textContent='AI 处理失败';toast(err.message,'error');}
  finally{buttons.forEach(button=>button.disabled=false);}
}

function renderRecipientList(){const q=($('#recipientSearch')?.value||'').toLowerCase();const rows=state.contacts.filter(c=>c.status==='active'&&`${c.first_name} ${c.last_name} ${c.email} ${c.company}`.toLowerCase().includes(q));const list=$('#recipientList');if(!list)return;list.innerHTML=rows.length?`<label class="recipient-row"><input class="checkbox" type="checkbox" id="selectAllRecipients"><div><strong>选择当前 ${rows.length} 位</strong></div></label>`+rows.map(c=>`<label class="recipient-row"><input class="checkbox recipient-check" type="checkbox" value="${c.id}" ${state.selectedContacts.has(c.id)?'checked':''}><div><strong>${escapeHtml(`${c.first_name} ${c.last_name}`.trim()||c.email)}</strong><span>${escapeHtml(c.email)}${c.company?' · '+escapeHtml(c.company):''}</span></div></label>`).join(''):emptyState('search','没有匹配联系人');$$('.recipient-check',list).forEach(input=>input.onchange=()=>{input.checked?state.selectedContacts.add(Number(input.value)):state.selectedContacts.delete(Number(input.value));updateRecipientSelection();});const all=$('#selectAllRecipients');if(all)all.onchange=()=>{rows.forEach(c=>all.checked?state.selectedContacts.add(c.id):state.selectedContacts.delete(c.id));renderRecipientList();updateRecipientSelection();};updateSelectedCount();icons();}
function updateSelectedCount(){const el=$('#selectedCount');if(el)el.textContent=`${composeRecipientEmails().length} 已选择`;}
async function submitCampaign(){const sender=$('#senderEmail').value.trim();const subject=$('#subject').value.trim();const html=$('#editor').innerHTML.trim();const manual=directRecipientEmails();const invalid=directRecipientEntries().find(value=>!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value));const recipientCount=composeRecipientEmails().length;if(!/^[^\s@]+@zhanyimetal\.com$/i.test(sender)){toast('发件邮箱必须使用 @zhanyimetal.com 域名','error');return;}if(invalid){toast(`收件邮箱格式不正确：${invalid}`,'error');$('#directRecipients').focus();return;}if(!subject||!html){toast('请填写主题和正文','error');return;}if(!recipientCount){toast('请填写或选择收件人','error');return;}if(!confirm(`确认将邮件加入队列，发送给 ${recipientCount} 位收件人？`))return;const button=$('#sendCampaign');button.disabled=true;const data=new FormData();data.append('payload',JSON.stringify({source:'compose',name:$('#campaignName').value.trim()||subject,from_email:sender,subject,html_body:html,contact_ids:[...state.selectedContacts],extra_emails:manual}));[...$('#attachmentInput').files].forEach(f=>data.append('attachments',f));try{const r=await api('/api/campaigns',{method:'POST',body:data});toast(r.contacts_created?`已加入队列，共 ${r.recipient_count} 封；新增 ${r.contacts_created} 位联系人`:`已加入队列，共 ${r.recipient_count} 封`);await loadSummary();renderCampaigns();}catch(err){toast(err.message,'error');button.disabled=false;}}

function bulkVisibleContacts(){const q=($('#bulkRecipientSearch')?.value||'').toLowerCase();return state.contacts.filter(c=>c.status==='active'&&`${c.first_name} ${c.last_name} ${c.email} ${c.company}`.toLowerCase().includes(q));}
function updateBulkCount(){const n=state.selectedContacts.size;const el=$('#bulkSelectedCount');if(el)el.textContent=`${n} 已选择`;const btn=$('#bulkSendCount');if(btn)btn.textContent=n;}
function renderBulkRecipientList(){const rows=bulkVisibleContacts();const list=$('#bulkRecipientList');if(!list)return;list.innerHTML=rows.length?rows.map(c=>`<label class="recipient-row"><input class="checkbox bulk-check" type="checkbox" value="${c.id}" ${state.selectedContacts.has(c.id)?'checked':''}><div><strong>${escapeHtml(`${c.first_name} ${c.last_name}`.trim()||c.email)}</strong><span>${escapeHtml(c.email)}${c.company?' · '+escapeHtml(c.company):''}</span></div></label>`).join(''):emptyState('search','没有匹配联系人');$$('.bulk-check',list).forEach(input=>input.onchange=()=>{input.checked?state.selectedContacts.add(Number(input.value)):state.selectedContacts.delete(Number(input.value));updateBulkCount();});updateBulkCount();icons();}
async function renderBulkCreate(){
  state.view='campaigns';state.bulkCreateOpen=true;state.selectedContacts=new Set();setActiveNav();setTitle('新建批量任务','BULK SEND');
  state.contacts=await api('/api/contacts');state.templates=await api('/api/letter-templates');
  const settings=await api('/api/settings');const aiReady=settings.ai_configured;
  const sendTemplates=state.templates.filter(t=>t.kind==='send');
  content.innerHTML=`<div class="section-head"><button class="secondary" id="bulkBack"><i data-lucide="arrow-left"></i>发送记录</button><div><h2>新建批量任务</h2><span class="muted">批量选择联系人 → 套用发信模板 → 可选 AI 逐条个性化优化 → 依次发送</span></div></div><div class="compose-layout"><section class="compose-panel"><div class="compose-fields"><div class="line-field"><span>发件人</span><input id="bulkSender" type="email" value="${escapeHtml(ZHANYI_FROM)}" pattern="[^\s@]+@zhanyimetal\.com" required></div><div class="line-field"><span>任务名称</span><input id="bulkName" placeholder="客户跟进"></div><div class="line-field"><span>发信模板</span><select id="bulkTemplate"><option value="">选择模板…</option>${sendTemplates.map(t=>`<option value="${t.id}">${escapeHtml(t.name)}</option>`).join('')}</select></div><div class="line-field"><span>邮件主题</span><input id="bulkSubject" placeholder="主题，可使用 {{first_name}}"></div><div class="line-field"><span>其他邮箱</span><input id="bulkExtra" inputmode="email" autocomplete="off" spellcheck="false" placeholder="选填，多个用逗号分隔"></div></div><div class="editor-toolbar"><button data-command="bold" title="粗体"><i data-lucide="bold"></i></button><button data-command="italic" title="斜体"><i data-lucide="italic"></i></button><button data-command="underline" title="下划线"><i data-lucide="underline"></i></button><button data-command="insertUnorderedList" title="项目列表"><i data-lucide="list"></i></button><button data-command="insertOrderedList" title="编号列表"><i data-lucide="list-ordered"></i></button><button data-command="createLink" title="链接"><i data-lucide="link"></i></button><button data-command="removeFormat" title="清除格式"><i data-lucide="eraser"></i></button></div><div id="bulkEditor" class="editor" contenteditable="true" data-placeholder="选择发信模板后自动填入，也可手动编辑；可使用 {{first_name}}、{{company}} 等变量"></div><div class="compose-footer"><label class="ai-opt"><input type="checkbox" id="bulkAiToggle" ${aiReady?'':'disabled'}><span>AI 逐条个性化优化<span class="ai-opt-hint">${aiReady?'结合每位联系人的公司、标签、备注与往来记录，逐条改写后发送':'未配置 AI（服务器缺少 SILICONFLOW_API_KEY），当前不可用'}</span></span></label><button class="primary" id="bulkSend"><i data-lucide="send"></i>发送给 <span id="bulkSendCount">0</span> 位联系人</button></div></section><aside class="recipient-panel"><div class="recipient-head"><strong>联系人</strong><span class="muted" id="bulkSelectedCount">0 已选择</span></div><div class="recipient-tools bulk-tools"><input class="recipient-search" id="bulkRecipientSearch" placeholder="搜索联系人"><div class="bulk-actions"><button class="secondary" id="bulkSelectAll"><i data-lucide="list-checks"></i>全选当前</button><button class="secondary" id="bulkClearSelection"><i data-lucide="x"></i>清空选择</button></div></div><div class="recipient-list" id="bulkRecipientList"></div></aside></div>`;
  $('#bulkBack').onclick=()=>renderCampaigns();
  $$('.editor-toolbar [data-command]').forEach(b=>b.onclick=()=>{const cmd=b.dataset.command;let value=null;if(cmd==='createLink')value=prompt('链接地址');document.execCommand(cmd,false,value);$('#bulkEditor').focus();});
  $('#bulkTemplate').onchange=()=>{const t=state.templates.find(x=>x.id===Number($('#bulkTemplate').value));if(!t)return;if(t.subject)$('#bulkSubject').value=t.subject;if(t.body)$('#bulkEditor').innerText=t.body;toast(`已套用模板：${t.name}`);};
  $('#bulkRecipientSearch').oninput=renderBulkRecipientList;
  $('#bulkSelectAll').onclick=()=>{bulkVisibleContacts().forEach(c=>state.selectedContacts.add(c.id));renderBulkRecipientList();};
  $('#bulkClearSelection').onclick=()=>{state.selectedContacts=new Set();renderBulkRecipientList();};
  $('#bulkSend').onclick=submitBulkCampaign;
  renderBulkRecipientList();
}
async function submitBulkCampaign(){
  const sender=$('#bulkSender').value.trim();const subject=$('#bulkSubject').value.trim();const html=$('#bulkEditor').innerHTML.trim();
  const manual=($('#bulkExtra').value||'').split(/[\n,;]+/).map(v=>v.trim()).filter(Boolean);
  const invalid=manual.find(value=>!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value));
  const recipientCount=state.selectedContacts.size+manual.filter(m=>!selectedContactEmails().includes(m.toLowerCase())).length;
  if(!/^[^\s@]+@zhanyimetal\.com$/i.test(sender)){toast('发件邮箱必须使用 @zhanyimetal.com 域名','error');return;}
  if(invalid){toast(`收件邮箱格式不正确：${invalid}`,'error');return;}
  if(!subject||!html||html==='<br>'){toast('请选择发信模板并确认主题和正文已填写','error');return;}
  if(!recipientCount){toast('请至少选择一位联系人','error');return;}
  const ai=$('#bulkAiToggle').checked;
  if(!confirm(`确认${ai?'使用 AI 逐条个性化优化并 ':''}发送给 ${recipientCount} 位收件人？`))return;
  const button=$('#bulkSend');button.disabled=true;
  const data=new FormData();data.append('payload',JSON.stringify({source:'bulk',name:$('#bulkName').value.trim()||subject,from_email:sender,subject,html_body:html,template_id:$('#bulkTemplate').value||null,ai_optimize:ai,contact_ids:[...state.selectedContacts],extra_emails:manual}));
  try{const r=await api('/api/campaigns',{method:'POST',body:data});toast(ai?`已加入队列，共 ${r.recipient_count} 封，将逐条 AI 优化后发送`:`已加入队列，共 ${r.recipient_count} 封`);await loadSummary();await renderCampaigns();}catch(err){toast(err.message,'error');button.disabled=false;}
}

async function renderCampaigns(){state.view='campaigns';state.bulkCreateOpen=false;setActiveNav();setTitle('批量任务','CAMPAIGNS');state.campaigns=await api('/api/campaigns?source=bulk');const totals=state.campaigns.reduce((a,c)=>{a.total+=c.total_count;a.sent+=c.sent_count;a.failed+=c.failed_count;if(['queued','sending'].includes(c.status))a.active++;return a;},{total:0,sent:0,failed:0,active:0});content.innerHTML=`<div class="campaign-grid"><div class="metric"><span>全部邮件</span><strong>${totals.total}</strong></div><div class="metric"><span>成功提交</span><strong>${totals.sent}</strong></div><div class="metric"><span>发送失败</span><strong>${totals.failed}</strong></div><div class="metric"><span>进行中任务</span><strong>${totals.active}</strong></div></div><div class="section-head collapse-head" id="campaignRecordsHead"><div class="collapse-title"><i class="fold-icon" data-lucide="chevron-right"></i><h2>发送记录</h2><span class="muted">${state.campaigns.length} 个任务</span></div><button class="primary" id="newCampaign"><i data-lucide="square-pen"></i>新建任务</button></div><div class="data-panel" id="campaignRecordsPanel">${state.campaigns.length?`<table class="data-table"><thead><tr><th>任务</th><th>进度</th><th>状态</th><th>创建时间</th><th></th></tr></thead><tbody>${state.campaigns.map(c=>{const pct=c.total_count?Math.round((c.sent_count+c.failed_count)/c.total_count*100):0;return `<tr><td class="contact-name"><strong>${escapeHtml(c.name)}</strong>${c.ai_optimize?'<span class="tag ai-tag">AI 优化</span>':''}<span>${escapeHtml(c.from_email||ZHANYI_FROM)} · ${escapeHtml(c.subject)}</span></td><td><strong>${c.sent_count} / ${c.total_count}</strong>${c.failed_count?` <span style="color:var(--red)">失败 ${c.failed_count}</span>`:''}<div class="progress"><i style="width:${pct}%"></i></div></td><td><span class="status ${escapeHtml(c.status)}">${escapeHtml(statusLabel(c.status))}</span></td><td>${formatDate(c.created_at)}</td><td class="actions"><button class="text-button campaign-detail" data-id="${c.id}">详情</button></td></tr>`}).join('')}</tbody></table>`:emptyState('layers-3','暂无批量任务')}</div>`;let folded=false;try{folded=localStorage.getItem('campaignRecordsFolded')==='1';}catch{}$('#campaignRecordsHead').classList.toggle('folded',folded);$('#campaignRecordsPanel').classList.toggle('hidden',folded);$('#campaignRecordsHead').onclick=e=>{if(e.target.closest('#newCampaign'))return;const panel=$('#campaignRecordsPanel');const next=!panel.classList.contains('hidden');panel.classList.toggle('hidden',next);$('#campaignRecordsHead').classList.toggle('folded',next);try{localStorage.setItem('campaignRecordsFolded',next?'1':'0');}catch{}};$('#newCampaign').onclick=renderBulkCreate;$$('.campaign-detail').forEach(b=>b.onclick=()=>campaignDetail(Number(b.dataset.id)));icons();}
async function campaignDetail(id){const c=await api(`/api/campaigns/${id}`);openModal(`<div class="modal-header"><div><h2>${escapeHtml(c.name)}</h2><span class="muted">${escapeHtml(c.subject)}${c.ai_optimize?' · AI 个性化':''}</span></div><button class="icon-button modal-close"><i data-lucide="x"></i></button></div><div class="modal-body"><div class="campaign-grid"><div class="metric"><span>总数</span><strong>${c.total_count}</strong></div><div class="metric"><span>成功</span><strong>${c.sent_count}</strong></div><div class="metric"><span>失败</span><strong>${c.failed_count}</strong></div><div class="metric"><span>状态</span><strong style="font-size:15px">${escapeHtml(statusLabel(c.status))}</strong></div></div><div class="data-panel"><table class="data-table"><thead><tr><th>收件人</th><th>主题</th><th>状态</th><th>错误</th></tr></thead><tbody>${c.recipients.map(r=>`<tr><td>${escapeHtml(r.email)}</td><td>${escapeHtml(r.subject||'—')}</td><td><span class="status ${escapeHtml(r.status)}">${escapeHtml(statusLabel(r.status))}</span></td><td>${escapeHtml(r.error||'—')}</td></tr>`).join('')}</tbody></table></div></div><div class="modal-footer">${c.failed_count?'<button class="secondary" id="retryCampaign"><i data-lucide="rotate-ccw"></i>重试失败项</button>':''}<button class="primary modal-close">关闭</button></div>`,true);$$('.modal-close').forEach(b=>b.onclick=closeModal);if($('#retryCampaign'))$('#retryCampaign').onclick=async()=>{const r=await api(`/api/campaigns/${id}/retry`,{method:'POST'});closeModal();toast(`已重试 ${r.queued} 封`);renderCampaigns();};}

async function renderForwarding(){state.view='forwarding';setActiveNav();setTitle('自动抄送','FORWARDING');state.forwardingRules=await api('/api/forwarding-rules');content.innerHTML=`<div class="section-head"><h2>抄送邮箱</h2><span class="muted">${state.forwardingRules.length} 个地址</span></div><div class="data-panel forwarding-panel"><form class="forwarding-form" id="forwardingForm"><label><span>邮箱地址</span><input id="forwardingEmail" type="email" placeholder="name@example.com" required></label><button class="primary" type="submit"><i data-lucide="plus"></i>添加</button></form>${state.forwardingRules.length?`<table class="data-table forwarding-table"><thead><tr><th>邮箱</th><th>已抄送</th><th>最近状态</th><th>添加时间</th><th></th></tr></thead><tbody>${state.forwardingRules.map(r=>`<tr><td><strong>${escapeHtml(r.email)}</strong></td><td>${r.sent_count||0} 封</td><td>${r.last_status?`<span class="status ${escapeHtml(r.last_status)}">${escapeHtml(statusLabel(r.last_status))}</span>`:'—'}</td><td>${formatDate(r.created_at)}</td><td class="actions"><button class="icon-button delete-forwarding" data-id="${r.id}" title="删除"><i data-lucide="trash-2"></i></button></td></tr>`).join('')}</tbody></table>`:emptyState('forward','暂无自动抄送邮箱')}</div>`;$('#forwardingForm').onsubmit=async event=>{event.preventDefault();const input=$('#forwardingEmail');const button=event.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/forwarding-rules',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:input.value.trim()})});toast('抄送邮箱已添加');await loadSummary();await renderForwarding();}catch(err){toast(err.message,'error');button.disabled=false;input.focus();}};$$('.delete-forwarding').forEach(button=>button.onclick=async()=>{if(!confirm('确认删除这个自动抄送邮箱？'))return;try{await api(`/api/forwarding-rules/${button.dataset.id}`,{method:'DELETE'});toast('抄送邮箱已删除');await loadSummary();await renderForwarding();}catch(err){toast(err.message,'error');}});icons();}

async function renderTemplates(){state.view='templates';setActiveNav();setTitle('通用模板','LETTER TEMPLATES');state.templates=await api('/api/letter-templates');const kindLabel=kind=>kind==='reply'?'回信':'发信';content.innerHTML=`<div class="section-head"><div><h2>通用发信 / 回信</h2><span class="muted">${state.templates.length} 条模板，写邮件时可一键填入主题和正文</span></div><button class="primary" id="newTemplate"><i data-lucide="plus"></i>新增模板</button></div><div class="data-panel">${state.templates.length?`<table class="data-table"><thead><tr><th>名称</th><th>类型</th><th>主题</th><th>更新时间</th><th></th></tr></thead><tbody>${state.templates.map(t=>`<tr><td class="contact-name"><strong>${escapeHtml(t.name)}</strong><span>${escapeHtml((t.body||'').replace(/\s+/g,' ').slice(0,80))}</span></td><td><span class="tag">${kindLabel(t.kind)}</span></td><td>${escapeHtml(t.subject||'—')}</td><td>${formatDate(t.updated_at||t.created_at)}</td><td class="actions"><button class="text-button edit-template" data-id="${t.id}">编辑</button></td></tr>`).join('')}</tbody></table>`:emptyState('notebook-pen','暂无通用模板','新增一条后，写邮件时可在顶部下拉直接套用')}</div>`;$('#newTemplate').onclick=()=>templateModal();$$('.edit-template').forEach(b=>b.onclick=()=>templateModal(state.templates.find(t=>t.id===Number(b.dataset.id))));icons();}
function templateModal(t={}){
  openModal(`<form id="templateForm"><div class="modal-header"><h2>${t.id?'编辑模板':'新增模板'}</h2><button type="button" class="icon-button modal-close"><i data-lucide="x"></i></button></div><div class="modal-body"><div class="form-grid"><label class="field"><span>名称</span><input name="name" required value="${escapeHtml(t.name||'')}" placeholder="如：开发信模板"></label><label class="field"><span>类型</span><select name="kind"><option value="send" ${t.kind!=='reply'?'selected':''}>发信</option><option value="reply" ${t.kind==='reply'?'selected':''}>回信</option></select></label><label class="field span-2"><span>主题</span><input name="subject" value="${escapeHtml(t.subject||'')}" placeholder="可使用 {{first_name}}、{{company}}"></label><label class="field span-2"><span>正文</span><textarea name="body" rows="12">${escapeHtml(t.body||'')}</textarea></label></div><p class="form-error" id="templateError"></p></div><div class="modal-footer">${t.id?'<button type="button" class="danger" id="deleteTemplate"><i data-lucide="trash-2"></i>删除</button>':''}<button type="button" class="secondary modal-close">取消</button><button class="primary" type="submit">保存</button></div></form>`);
  $$('.modal-close').forEach(b=>b.onclick=closeModal);const form=$('#templateForm');
  form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));try{await api(t.id?`/api/letter-templates/${t.id}`:'/api/letter-templates',{method:t.id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});closeModal();toast('模板已保存');await renderTemplates();}catch(err){$('#templateError').textContent=err.message;}};
  if(t.id)$('#deleteTemplate').onclick=async()=>{if(!confirm('确定删除该模板？'))return;await api(`/api/letter-templates/${t.id}`,{method:'DELETE'});closeModal();toast('模板已删除');await renderTemplates();};
}

async function renderSettings(){state.view='settings';setActiveNav();setTitle('设置','SYSTEM');const s=await api('/api/settings');content.innerHTML=`<div class="settings-grid"><section class="settings-panel"><h3>发件身份</h3><div class="setting-row"><span>名称</span><strong class="setting-value">${escapeHtml(s.from_name)}</strong></div><div class="setting-row"><span>邮箱</span><strong class="setting-value">${escapeHtml(s.from_email)}</strong></div><div class="setting-row"><span>Resend API</span><span class="status ${s.resend_configured?'delivered':'failed'}">${s.resend_configured?'已配置':'未配置'}</span></div></section><section class="settings-panel"><h3>自动抄送</h3><div class="setting-row"><span>通道</span><strong class="setting-value">${escapeHtml(s.forwarding_provider)}</strong></div><div class="setting-row"><span>发件邮箱</span><strong class="setting-value">${escapeHtml(s.forwarding_sender)}</strong></div><div class="setting-row"><span>SMTP</span><span class="status ${s.forwarding_configured?'delivered':'failed'}">${s.forwarding_configured?'已配置':'未配置'}</span></div></section><section class="settings-panel"><h3>AI 写作</h3><div class="setting-row"><span>SiliconFlow</span><span class="status ${s.ai_configured?'delivered':'failed'}">${s.ai_configured?'已配置':'未配置'}</span></div><div class="setting-row"><span>模型</span><strong class="setting-value">${escapeHtml(s.ai_model)}</strong></div></section><section class="settings-panel"><h3>接收 Webhook</h3><div class="code-box">${escapeHtml(s.webhook_url)}</div></section></div>`;icons();}

async function navigate(view){state.search='';$('#globalSearch').value='';if(view==='inbox')await renderMail('inbound');else if(view==='forwarding')await renderForwarding();else if(view==='sent')await renderMail('outbound');else if(view==='contacts')await renderContacts();else if(view==='compose')await renderCompose();else if(view==='campaigns')await renderCampaigns();else if(view==='bulk-create')await renderBulkCreate();else if(view==='lead-imports')await renderLeadImports();else if(view==='templates')await renderTemplates();else if(view==='settings')await renderSettings();$('#sidebar').classList.remove('open');}
$$('[data-view]').forEach(button=>button.onclick=()=>navigate(button.dataset.view));$('#menuButton').onclick=()=>$('#sidebar').classList.toggle('open');$('#modalBackdrop').onclick=e=>{if(e.target===e.currentTarget)closeModal();};$('#logoutButton').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload();};$('#refreshButton').onclick=()=>navigate(state.bulkCreateOpen?'bulk-create':state.view);let searchTimer;$('#globalSearch').oninput=e=>{state.search=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(state.view==='inbox')renderMail('inbound');else if(state.view==='sent')renderMail('outbound');else if(state.view==='contacts')renderContacts();else if(state.view==='lead-imports')renderLeadImportTable();},250);};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
loadSummary().then(()=>navigate('inbox')).catch(err=>toast(err.message,'error'));setInterval(()=>{loadSummary();if(state.view==='campaigns'&&!state.bulkCreateOpen)renderCampaigns();},10000);icons();
